\label{dfn16}
		(Sub-Laplacian)  The \textbf{sub-Laplacian} $\mathcal{L}$ on $\mathcal{H}_{3}$ is defined by,
		\begin{align}\label{21}
			\mathcal{L}=-\left(X^{2}+Y^{2}\right)
		\end{align}

Suppose, $u\in \mathcal{S}'(\mathcal{H}_{3})\cap C^{\infty}(\mathcal{H}_{3})$ be such that, $\check{u}(z,\tau)$ is a tempered distribution of $\tau$ on $\mathbb{R}$,  $\forall$ \hspace{10pt} $z\in \mathbb{C}$, where, $\check{u}$ denotes the \textit{Inverse Fourier Transform} of $u$ with respect to time $t$. Then, for almost every $\tau\in \mathbb{R}\setminus \{0\}$,
		\begin{align*}
			\left(\mathcal{L}u\right)^{\tau}=L_{\tau}u^{\tau}
		\end{align*}
		where,
		\begin{align*}
			\left(\mathcal{L}u\right)^{\tau}(z)=\left(\mathcal{L}u\right)^{\check{ }}(z)\mbox{ , \hspace{20pt}}z\in \mathbb{C}
		\end{align*}
		and,
		\begin{align*}
			u^{\tau}(z)=\check{u}(z,\tau)\mbox{ , \hspace{20pt}}z\in \mathbb{C}
		\end{align*}

\label{dfn17}
		The \textbf{Fourier-Wigner Transform} $V_{\tau}(f,g)$ of the functions $f,g\in \mathcal{S}(\mathbb{R})$ is defined by,
		\begin{align*}
			V_{\tau}(f,g)(q,p)=\frac{1}{\sqrt{2\pi}}|\tau|^{1/2}\int\limits_{-\infty}^{\infty}e^{i\tau q.y}f(y-2p)\overline{g(y+2p)}dy \mbox{ , \hspace{20pt}}\forall \hspace{10pt} q,p\in \mathbb{R}
		\end{align*}

\label{thm3}
		For $j,k=0,1,2,....$, the following holds true,
		\begin{align*}
			L_{\tau}e_{j,k,\tau}=(2k+1)|\tau|e_{j,k,\tau}
		\end{align*}

Proof is similar to the derivation cited in \cite[Theorem~22.2]{25}.\par 
		A priori from the statement of \cite[Theorem~22.1]{25}, it follows that, for $j=0,1,2,...$ and $k=0,1,2,.....$;
		\begin{align*}
			Z\overline{Z}e_{j,k}=i(2k+2)^{1/2}Ze_{j,k-1}=-(2k+2)e_{j,k}
		\end{align*}
		and,
		\begin{align*}
			\overline{Z}Ze_{j,k}=i(2k)^{1/2}Ze_{j,k-1}=-(2k)e_{j,k}
		\end{align*}
		Thus, \begin{align*}
			L_{\tau}e_{j,k}=-\frac{1}{2}\left(Z\overline{Z}+\overline{Z}Z\right)|\tau|e_{j,k,\tau}
		\end{align*}
		Important to observe that, the above identity also holds for $e_{j,0,\tau}$, where, $j=0,1,2,.....$ due to the fact that,
		\begin{align*}
			Ze_{j,0}=0\mbox{ , \hspace{20pt}}\forall \hspace{10pt} j=0,1,2,....
		\end{align*}

\label{dfn18}
		(Spectrum)  The \textbf{Resolvent Set} $\rho(\mathcal{T})$ of $\mathcal{T}$ is defined as follows,
		\begin{align*}
			\rho(\mathcal{T})\mbox{ }:=\mbox{ }\left\{\lambda\in \mathbb{C}\mbox{ }|\mbox{ }\mathcal{T}-\lambda I\mbox{ }:\mbox{ }\mathcal{D}(\mathcal{T})\longrightarrow X \mbox{  is bijective}\right\}
		\end{align*}
		Where, $I$ denotes the \textbf{identity operator} on $X$. \\
		The \textbf{Spectrum}, denoted by $\Sigma(\mathcal{T})$ is defined to be the complement of $\rho(\mathcal{T})$ in $\mathbb{C}$.

\label{dfn19}
		(Point Spectrum)  The \textbf{point spectrum} \cite{28} of $\mathcal{T}$, denoted by $\Sigma_{p}(\mathcal{T})$ is defined as,
		\begin{align*}
			\Sigma_{p}(\mathcal{T})\mbox{ }:=\mbox{ }\left\{\lambda\in \mathbb{C}\mbox{ }|\mbox{ }\mathcal{T}-\lambda I\mbox{ }:\mbox{ }\mathcal{D}(\mathcal{T})\longrightarrow X \mbox{  is not injective}\right\}
		\end{align*}

\label{dfn20}
		(Continuous Spectrum)  The \textbf{Continuous Spectrum} of $\mathcal{T}$, denoted by $\Sigma_{c}(\mathcal{T})$, is defined as,
		\begin{align*}
			\Sigma_{c}(\mathcal{T})\mbox{ }:=\mbox{ }\left\{\lambda\in \mathbb{C}\mbox{ }|\mbox{ }Range(\mathcal{T}-\lambda I)\mbox{ } \mbox{  is dense in }X\mbox{ ,  }(\mathcal{T}-\lambda I)^{-1}\mbox{ exists, but is unbounded}\right\}
		\end{align*}

\label{dfn21}
		(Residual Spectrum)  The \textbf{Residual Spectrum} of $\mathcal{T}$, denoted by $\Sigma_{r}(\mathcal{T})$, is defined as,
		\begin{align*}
			\Sigma_{r}(\mathcal{T})\mbox{ }:=\mbox{ }\left\{\lambda\in \mathbb{C}\mbox{ }|\mbox{ }Range(\mathcal{T}-\lambda I)\mbox{ } \mbox{  is not dense in }X\mbox{ ,  }(\mathcal{T}-\lambda I)^{-1}\mbox{ exists and is bounded}\right\}
		\end{align*}

\label{prop4}
		A priori given a complex and separable Hilbert Space $X$, if $\mathcal{T}$ is a self-adjoint operator , then,
		\begin{align*}
			\Sigma_{r}(\mathcal{T})=\phi
		\end{align*}

\label{thm4}
		We have,
		\begin{align*}
			\Sigma(\mathcal{L}_{0})=\Sigma_{c}(\mathcal{L}_{0})=\left[0,\infty\right)
		\end{align*}

We first intend to show that, no eigenvalue of $\mathcal{L}_{0}$ lies in the interval $\left[0,\infty \right)$. We know for a fact that, $0$ is not an eigenvalue of $\mathcal{L}_{0}$ ( Proof mentioned in \cite{22}). Suppose, $\lambda$ be a positive number such that, $\exists$ a function $u\in L^{2}(\mathcal{H}_{3})$ satisfying,
		\begin{align*}
			\mathcal{L}_{0}u=\lambda u
		\end{align*}
		Consequently,
		\begin{align*}
			L_{\tau}u^{\tau}=\lambda u^{\tau}
		\end{align*}
		Although, the above relation implies that, $u^{\tau}=0$, \hspace{10pt}$\forall$ $\tau\in \mathbb{R}\setminus \{0\}$ and,
		\begin{align}
			|\tau|\neq \frac{\lambda}{(2k+1)}\mbox{ , }\hspace{20pt}k=0,1,2,\cdots 
		\end{align}
		This helps us conclude that, $u=0$, a contradiction. Moreover, $\mathcal{L}_{0}$ being \textit{self-adjoint}, it implies,
		\begin{align*}
			\Sigma(\mathcal{L}_{0})=\Sigma_{c}(\mathcal{L}_{0})
		\end{align*}
		Thus, it only suffices to establish that, $(\mathcal{L}_{0}-\lambda I)$ is not \textit{surjective}  $\forall$ \hspace{10pt}$\lambda\in \left[0,\infty\right)$. \par 
		Assuming $(\mathcal{L}_{0}-\lambda I)$ to be surjective for some $\lambda_{0}\in \left[0,\infty\right)$, we can infer that, $\lambda_{0}\in \rho(\mathcal{L}_{0})$. Hence, $\exists$ an open interval $I_{\lambda_{0}}\subset \rho(\mathcal{L}_{0})$ containing $\lambda_{0}$.\par 
		Define $f$ on $\mathcal{H}$ as,
		\begin{align*}
			f(x,y,t)=h(x,y)e^{-\frac{t^{2}}{2}}\mbox{ , }\hspace{10pt} x,y,t\in \mathbb{R}
		\end{align*}
		Where, $h\in L^{2}(\mathbb{R}^{2})$.\par 
		Therefore, for every $\lambda \in I_{\lambda_{0}}$, $\exists$ a function $u_{\lambda}\in L^{2}(\mathcal{H}_{3})$, such that,
		\begin{align*}
			(\mathcal{L}_{0}-\lambda I)u_{\lambda}=f
		\end{align*}
		Computing the \textit{Inverse Transform} with respect to $t$ helps us conclude,
		\begin{align}
			(L_{\tau}-\lambda I)u^{\tau}_{\lambda}=he^{-\frac{\tau^{2}}{2}}\mbox{ , }\hspace{20pt} \mbox{ for almost every }\tau\in \mathbb{R}\setminus\{0\}
		\end{align}
		As a consequence, $(L_{\tau}-\lambda I)$ is \textit{surjective} $\forall$\hspace{10pt}$\tau\in S_{\lambda}$ for which the \textit{lebesgue measure}, 
		\begin{align*}
			m(\mathbb{R}\setminus S_{\lambda})=0
		\end{align*}
		Consider, $\tau\in \bigcap\limits_{r\in I_{\lambda_{0}}\cap \mathbb{Q}}S_{r}$ , $\mathbb{Q}$ being the set of all \textit{rationals}. Hence, $(L_{\tau}-\lambda I)$ is surjective, and subsequently \textit{injective} for every $\lambda\in I_{\lambda_{0}}\cap \mathbb{Q}$.\par 
		Thus, $L_{\tau}-\lambda I$ is \textit{bijective}, \hspace{5pt} $\forall$ $\lambda\in I_{\lambda_{0}}$. ( Use the fact that, the \textit{Resolvent Set} of $L_{\tau}$ is \textit{open} ) Furthermore, we can also observe that, $(L_{\tau}-\lambda I)$ is \textit{injective} iff, 
		\begin{align*}
			\lambda\neq (2k+1)|\tau|\mbox{ , }\hspace{20pt}k=0,1,2,\cdots 
		\end{align*}
		A contradiction to the fact that, if we assume $\tau\in \bigcap\limits_{r\in I_{\lambda_{0}}}S_{r}$ to be sufficiently small, such that, $(2k+1)|\tau|\in I_{\lambda_{0}}$ for some $k=0,1,2,\cdots$. Hence, the proof is done.

\label{dfn22}
		The \textbf{Essential Spectrum} of $\mathcal{T}$, denoted as $\Sigma_{DS}(\mathcal{T})$  [\textit{Dunford} and Schwartz \cite{29} ] is defined as follows,
		\begin{align*}
			\Sigma_{DS}(\mathcal{T})\mbox{ }:=\mbox{ }\left\{\lambda\in \mathbb{C}\mbox{ }|\mbox{ }Range(\mathcal{T}-\lambda I)\mbox{ } \mbox{  is not closed in }X\right\}
		\end{align*}

\label{thm5}
		We shall have,
		\begin{align}
			\Sigma_{DS}(\mathcal{L}_{0})=\Sigma_{W}(\mathcal{L}_{0})=\Sigma_{S}(\mathcal{L}_{0})=\left[0,\infty\right)
		\end{align}

It only requires us to verify that,
		\begin{align*}
			\left[0,\infty\right)\subseteq \Sigma_{DS}(\mathcal{L}_{0})
		\end{align*}
		Assume, $\lambda\in \left[0,\infty\right)$, although, $\lambda\notin \Sigma_{DS}(\mathcal{L}_{0})$. Thus, $Range(\mathcal{L}_{0}-\lambda I)$ is \textit{closed} in $L^{2}(\mathcal{H}_{3})$. This in turn helps us conclude that, $\mathcal{L}_{0}-\lambda I$ is \textit{bijective}, i.e., $\lambda\in \mathcal{L}_{0}$, a contradiction. Hence the proof is complete.

\label{rmk6}
		Similar technique can be implemented to compute the \textit{Spectrum} of the unique \textbf{self-adjoint extension} $\Delta_{\mathcal{H}_{3},0}$ of the \textit{Laplacian} $\Delta_{\mathcal{H}_{3}}$ on the \textit{Heisenberg Group} $\mathcal{H}_{3}$ defined as,
		\begin{align*}
			\Delta_{\mathcal{H}_{3}}=-\left(X^{2}+Y^{2}+T^{2}\right)
		\end{align*}
		In fact, we have \cite{33},
		\begin{align*}
			\Sigma\left(\Delta_{\mathcal{H}_{3},0}\right)=\Sigma_{c}\left(\Delta_{\mathcal{H}_{3},0}\right)=\left[0,\infty\right)
		\end{align*}
		Therefore, we can infer,
		\begin{align}
			\Sigma_{DS}(\Delta_{\mathcal{H}_{3},0})=\Sigma_{W}(\Delta_{\mathcal{H}_{3},0})=\Sigma_{S}(\Delta_{\mathcal{H}_{3},0})=\left[0,\infty\right)
		\end{align}

(Kor$\acute{a}$nyi Norm)  It can be observed that, the anisotropic dilation structure on the Heisenberg Group $\mathcal{H}_{n}$ induces the \textbf{Kor$\acute{a}$nyi Norm} defined as follows: 
		\begin{align*}
			r(\xi):=r(z,t)=(|z|^{4}+t^{2})^{\frac{1}{4}} \mbox{ , }\hspace{10pt}\forall \hspace{5pt} \xi=(z,t)\in \mathcal{H}_{n}
		\end{align*}

\label{rmk8}
		We can indeed infer that, the \textit{Haar Measure} on $\mathcal{H}_{n}$ is consistent with the \textit{Lebesgue Measure} on $\mathbb{R}^{2n+1}$, and is invariant under the left translations of $\mathcal{H}_{n}$. Moreover, it is $Q$-Homogeneous with respect to dilations ($Q$ denotes the \textit{Hausdorff Dimension}).\par 
		Thus, the \textit{topological dimension} of $\mathcal{H}_{n}$ (is equal to $2n+1$) is strictly less than $Q=2n+2$.

We define the \textbf{Horizontal Gradient} of a $C^{1}$-function $u:\mathcal{H}_{n}\longrightarrow \mathbb{R}$ as:
		\begin{align}
			D_{H}(u)=\sum\limits_{j=1}^{n}\left((X_{j}u)X_{j}+(Y_{j}u)Y_{j}\right)
		\end{align}

\label{dfn23}
		Given any horizontal vector field function, $X=X(\xi)$, $X=\{x^{j}X_{j}+\tilde{x}^{j}Y_{j}\}_{j=1(1)n}$ of class $C^{1}(\mathcal{H}_{n},\mathbb{R}^{2n})$, the \textbf{Horizontal Divergence} of $X$ is defined as,
		\begin{align*}
			div_{H}X=\sum\limits_{j=1}^{n}\left(X_{j}(x^{j})+Y_j(y^{j})\right)
		\end{align*}

(sub-Laplacian)  For every $u\in C^{2}(\mathcal{H}_{n})$, the \textbf{sub-Laplacian} or, \textit{Kohn-Spencer Laplacian} of $u$ is defined as:
		\begin{align*}
			\Delta_{H}(u)=\sum\limits_{j=1}^{n}\left(X^{2}_{j}+Y^{2}_{j}\right)u
		\end{align*} 
		\begin{align}
			=\sum\limits_{j=1}^{n}\left(\frac{\partial^{2}}{\partial x^{2}_{j}}+\frac{\partial^{2}}{\partial y^{2}_{j}}+4y_{j}\frac{\partial^{2}}{\partial x_{j}\partial t}-4x_{j}\frac{\partial^{2}}{\partial y_{j}\partial t}\right)u+4|z|^{2}\frac{\partial^{2}u}{\partial^{2} t}
		\end{align}

The standard \textbf{$L^{p}$-norm} is defined as,
		\begin{align*}
			||u||^{p}_{p}=\int\limits_{\omega}|u|^{p}d\xi \mbox{ , }\hspace{10pt} \forall \hspace{5pt} u\in \Omega
		\end{align*}

In fact, one can establish that, the best value of the constant $V_{0}$, denoted by $C_{p^{*}}$ is attained in the \textit{Folland-Stein Spaces} $S^{1,p}(\mathcal{H}_{n})$, which, also can be interpreted as the completion of $C^{\infty}_{c}(\mathcal{H}_{n})$ in terms of the norm,
		\begin{align*}
			||D_{H}(u)||_{p}=\left(\hspace{5pt} \int\limits_{\mathcal{H}_{n}}|D_{H}(u)|^{p}_{H}d\xi \hspace{5pt}\right)^{\frac{1}{p}}
		\end{align*}
		Thus, we can obtain the following estimate of $C_{p^{*}}$ of the \textit{Folland-Stein Inequality} as,
		\begin{align*}
			C_{p^{*}}=\inf\limits_{u\in S^{1,p}(\mathcal{H}_{n}),u\neq 0}\frac{||D_{H}(u)||^{p}_{p}}{||u||^{p}_{p^{*}}}
		\end{align*}
		For further details, see \cite{39}.

\label{dfn24}
		A sequence $\{u_{n}\}_{n\in \mathbb{N}}\subset X$ is termed as a \textbf{Palais-Smale Sequence} for the functional $\mathcal{J}_{\lambda}$ at level $c$ if,
		\begin{align}\label{36}
			\mathcal{J}_{\lambda}(u_{n})\longrightarrow c \mbox{ , }\hspace{20pt} \mathcal{J}'_{\lambda}(u_{n})\longrightarrow 0 \hspace{10pt} \mbox{ in }X' \mbox{ as } n\rightarrow +\infty 
		\end{align}

\label{thm7}
		A priori we assume that, \eqref{32} holds true. If $M$ satisfies conditions $(1)$ and $(2)$ of \eqref{33}, and $f$ verifies \eqref{34}. Additionally, suppose we consider that, one of the following condition also holds :
		\begin{enumerate}
			\item $\exists$ a positive constant $m^{*}>0$ for every $m_{0}>m^{*}$ and $\lambda>0$.
			\item $\exists$ a positive constant $\lambda_{2}>0$ for every $\lambda>\lambda_{2}$ and, $m_{0}>0$.
		\end{enumerate}
		Then, the problem \eqref{30} admits of at least $n$ pairs of non-trivial weak solutions in $HW^{1,p}_{V}(\mathcal{H}_{n})$.

\label{thm8}
		(Mountain Pass Theorem)  For a given real Banach Space $E$ and $\mathcal{J}\in C^{1}(E)$, satisfying $\mathcal{J}(0)=0$. We further assume that,
		\begin{enumerate}
			\item $\exists$ $\rho, \alpha>0$ such that, $\mathcal{J}(u)\geq \alpha$ \hspace{10pt}$\forall$ $u\in E$, with $||u||_{E}=\rho$;
			\item $\exists$ $e\in E$ satisfying $||e||_{E}>\rho$ such that, $\mathcal{J}(e)<0$
		\end{enumerate}
		If we denote, $\gamma:=\left\{\gamma\in C([0,1],E)\mbox{ }|\mbox{ } \gamma(0)=1 \mbox{ , }\gamma(1)=e\right\}$. Then,
		\begin{align}
			c=\inf\limits_{\gamma\in \Gamma}\max\limits_{0\leq t\leq 1}\mathcal{J}(\gamma(t)) \geq \alpha
		\end{align}
		and there exists a $(PS)_{c}$ sequence $\{u_{n}\}_{n} \subset E$.

\label{37}
		We shall have,
		\begin{align}
			0<c_{\lambda}=\inf\limits_{\gamma\in \Gamma}\max\limits_{0\leq t\leq 1}\mathcal{J}_{\lambda}(\gamma(t))<\left(\frac{1}{\theta}-\frac{1}{p^{*}}\right)\left(m_{0}C_{p^{*}}\right)^{\frac{p^{*}}{p^{*}-p}}
		\end{align}
		for large enough $\lambda$.

Choose $v_{0}\in HW^{1,p}_{V}(\mathcal{H}_{n})$ such that,
		\begin{align*}
			||v_{0}||=1 \mbox{ , and, }\hspace{20pt}\lim\limits_{t\rightarrow \infty}\mathcal{J}_{\lambda}(tv_{0})=-\infty
		\end{align*}
		Therefore, $\sup\limits_{t\geq 0}\mathcal{J}_{\lambda}(tv_{0})=\mathcal{J}_{\lambda}(t_{\lambda}v_{0})$ for some $t_{\lambda}>0$. Thus, $t_{\lambda}$ satisfies,
		\begin{align*}
			M\left(\left|\left|D_{H}(t_{\lambda}v_{0})\right|\right|^{p}_{p}+\left|\left|t_{\lambda}v_{0}\right|\right|^{p}_{p,V}\right).\left(\left|\left|D_{H}(t_{\lambda}v_{0})\right|\right|^{p}_{p}+\left|\left|t_{\lambda}v_{0}\right|\right|^{p}_{p,V}\right)
		\end{align*}
		\begin{align}\label{38}
			=\lambda \int\limits_{\mathcal{H}_{n}}f(\xi,t_{\lambda}v_{0})|t_{\lambda}v_{0}|^{2}d\xi + \int\limits_{\mathcal{H}_{n}}|t_{\lambda}v_{0}|^{p^{*}}d\xi
		\end{align}
		It suffices to prove that, $\{t_{\lambda}\}_{\lambda>0}$ is bounded. Since, $t_{\lambda}\geq 1$ $\forall$  $\lambda>0$. Thus, by property $(2)$ of \eqref{33} and \eqref{38}, we deuce that,
		\begin{center}
			$	\tau \mathcal{M}(1)t^{2p\tau}_{\lambda}\geq \tau \mathcal{M}(1)(||t_{\lambda}v_{0}||^{p})^{\tau}$
		\end{center}
		\begin{align*}
			\geq 	M\left(\left|\left|D_{H}(t_{\lambda}v_{0})\right|\right|^{p}_{p}+\left|\left|t_{\lambda}v_{0}\right|\right|^{p}_{p,V}\right).\left(\left|\left|D_{H}(t_{\lambda}v_{0})\right|\right|^{p}_{p}+\left|\left|t_{\lambda}v_{0}\right|\right|^{p}_{p,V}\right) \\
			=\lambda \int\limits_{\mathcal{H}_{n}}f(\xi,t_{\lambda}v_{0})|t_{\lambda}v_{0}|^{2}d\xi + \int\limits_{\mathcal{H}_{n}}|t_{\lambda}v_{0}|^{p^{*}}d\xi
		\end{align*}
		\begin{align}\label{39}
			\geq t^{p^{*}}_{\lambda}\int\limits_{\mathcal{H}_{n}}|v_{0}|^{p^{*}}d\xi 
		\end{align}
		It follows from \eqref{39} that, $\{t_{\lambda}\}_{\lambda>0}$ is bounded, since, $p\tau<p^{*}$.
		Next, we shall prove that, $t_{\lambda}\longrightarrow 0$ as, $\lambda\longrightarrow \infty$. By contradiction, suppose, $\exists$ $t_{0}>0$ and a sequence $\{\lambda_{n}\}_{n}$ with $\lambda_{n}\longrightarrow \infty$ as $n\rightarrow \infty$, and consequently, $t_{\lambda_{n}}\longrightarrow t_{0}$ as $n\rightarrow \infty$.\par 
		A simple application of the \textit{Lebesgue Dominated Convergence Theorem} yields,
		\begin{align*}
			\int\limits_{\mathcal{H}_{n}}f(\xi, t_{\lambda_{n}}v_{0})\left|t_{\lambda_{n}}v_{0}\right|^{2}d\xi \longrightarrow \int\limits_{\mathcal{H}_{n}}f(\xi, t_{\lambda}v_{0})\left|t_{\lambda}v_{0}\right|^{2}d\xi 
		\end{align*}
		as $n\rightarrow \infty$. Thus, we can conclude that, 
		\begin{align*}
			\lambda_{n}\int\limits_{\mathcal{H}_{n}}f(\xi, t_{\lambda}v_{0})\left|t_{\lambda}v_{0}\right|^{2}d\xi \longrightarrow \infty \mbox{ , as, }\hspace{10pt} n\rightarrow \infty
		\end{align*}
		A contradiction to the fact that, \eqref{38} holds true. Thus, $t_{\lambda}\longrightarrow 0$ as, $\lambda\rightarrow \infty$. Another deduction which can indeed be made from \eqref{38} is,
		\begin{align*}
			\lim\limits_{\lambda\rightarrow \infty}\lambda \int\limits_{\mathcal{H}_{n}}f(\xi, t_{\lambda}v_{0})\left|t_{\lambda}v_{0}\right|^{2}d\xi =0
		\end{align*}
		and,
		\begin{align*}
			\lim\limits_{\lambda\rightarrow \infty}\int\limits_{\mathcal{H}_{n}}\left|t_{\lambda}v_{0}\right|^{p^{*}}d\xi =0
		\end{align*}
		A priori, using the deduction, $t_{\lambda}\longrightarrow 0$ as, $\lambda\rightarrow \infty$ and the definition of $\mathcal{J}_{\lambda}$, we obtain,
		\begin{align*}
			\lim\limits_{\lambda\rightarrow \infty}\left(\sup\limits_{t\geq 0}\mathcal{J}_{\lambda}(tv_{0})\right)=	\lim\limits_{\lambda\rightarrow \infty}\mathcal{J}_{\lambda}(tv_{0})=0
		\end{align*}
		Hence, $\exists$ $\lambda_{1}>0$ satisfying for every $\lambda\geq \lambda_{1}$,
		\begin{align*}
			\sup\limits_{t\geq 0}\mathcal{J}_{\lambda}(tv_{0})<\left(\frac{1}{\theta}-\frac{1}{p^{*}}\right)\left(m_{0}C_{p^{*}}\right)^{\frac{p^{*}}{p^{*}-p}}
		\end{align*}
		Choosing $e=t_{1}v_{0}$, for large enough $t_{1}$, it can be verified that, 
		\begin{center}
			$\mathcal{J}_{\lambda}(e)<0$
		\end{center}
		\begin{align*}
			\implies 0<c_{\lambda}\leq \max\limits_{t\in [0,1]}\mathcal{J}_{\lambda}(\gamma(t))\hspace{40pt} \mbox{, by setting, }\gamma(t)=tt_{1}v_{0}
		\end{align*}
		Therefore, we conclude,
		\begin{align*}
			0<c_{\lambda}=\sup\limits_{t\geq 0}\mathcal{J}_{\lambda}(tv_{0})<\left(\frac{1}{\theta}-\frac{1}{p^{*}}\right)\left(m_{0}C_{p^{*}}\right)^{\frac{p^{*}}{p^{*}-p}}
		\end{align*}
		for $\lambda$ large enough, which completes the proof.

\label{thm9}
		For an infinite dimensional Banach Space $X$ and $\mathcal{J}\in C^{1}(X)$ be an even functional, such that, $\mathcal{J}(0)=0$. Further, we assume that, $X=Y\oplus Z$, $Y$ being finite dimensional. Then, $\mathcal{J}$ satisfies the following conditions,
		\begin{enumerate}
			\item $\exists$ constants $\rho, \alpha>0$ satisfying, $\mathcal{J}(u)\geq \alpha$ for every $u\in \partial B_{\rho}\cap Z$.
			\item $\exists$ $\Theta>0$ such that, $\mathcal{J}$ satisfies the $(PS)_{c}$ condition $\forall$ $c$, with $c\in (0,\Theta)$.
			\item Given any finite dimensional subspace $\tilde{X}\subset X$, $\exists$ $R=R(\tilde{X})>0$ satisfying $\mathcal{J}(u)\leq 0$ on $\tilde{X}\setminus B_{R}$
		\end{enumerate}

We shall apply Theorem \eqref{thm9} to $\mathcal{J}_{\lambda}$. A priori using the fact that, $HW^{1,p}_{V}(\mathcal{H}_{n})$ is indeed a \textbf{reflexive} \textit{Banach Space} and, $\mathcal{J}_{\lambda}\in C^{1}\left(HW^{1,p}_{V}(\mathcal{H}_{n})\right)$.\par 
		Applying \eqref{35}, we can infer that, the functional $\mathcal{J}_{\lambda}$ satisfies, $\mathcal{J}_{\lambda}(0)=0$. We shall thus prove the theorem in three steps.\\
		\textbf{\underline{Step 1 :}} \par 
		We can in fact obtain that, $\mathcal{J}_{\lambda}$ indeed satisfies $(1)$ and $(3)$ of Theorem \eqref{thm9}.\\
		\textbf{\underline{Step 2 :}} \par 
		We claim that, $\exists$ a monotone increasing sequeence $\{\Phi_{n}\}_{n}$ in $\mathbb{R}_{+}$, such that, 
		\begin{align*}
			c^{\lambda}_{n}=\inf\limits_{E\in \Gamma_{n}}\max\limits_{u\in E}\mathcal{J}_{\lambda}(u)<\Phi_{n}
		\end{align*} 
		The above definition of $	c^{\lambda}_{n}$ allows us to infer, 
		\begin{align*}
			c^{\lambda}_{n}=\inf\limits_{E\in \Gamma_{n}}\max\limits_{u\in E}\mathcal{J}_{\lambda}(u)\leq \inf\limits_{E\in \Gamma_{n}}\max\limits_{u\in E}\left\{\mathcal{M}\left(\left|\left|D_{H}(u)\right|\right|^{p}_{p}+||u||^{p}_{p,V}\right)-\frac{1}{p^{*}}\int\limits_{\mathcal{H}_{n}}|u|^{p^{*}}d\xi\right\}
		\end{align*}
		Set,
		\begin{align*}
			\Phi_{n}=\inf\limits_{E\in \Gamma_{n}}\max\limits_{u\in E}\left\{\mathcal{M}\left(\left|\left|D_{H}(u)\right|\right|^{p}_{p}+||u||^{p}_{p,V}\right)-\frac{1}{p^{*}}\int\limits_{\mathcal{H}_{n}}|u|^{p^{*}}d\xi\right\}
		\end{align*}
		Therefore, $\Phi_{n}<\infty$ and, $\Phi_{n}\leq \Phi_{n+1}$ \hspace{10pt}$\forall$ $n\in \mathbb{N}$ ( Follows from the definition of $\Gamma_{n}$ ).\\
		\textbf{\underline{Step 3 :}} \par 
		We claim that, the problem \eqref{30} has at least $k$ pairs of weak solutions. To this end, we distingish two cases:\\ 
		\textit{Case I :}\par 
		Fix $\lambda >0$. We set $m_{0}$ very large such that, 
		\begin{align*}
			\sup\limits_{n}\Phi_{n}<\left(\frac{1}{\theta}-\frac{1}{p^{*}}\right)\left(m_{0}C_{p^{*}}\right)^{\frac{p^{*}}{p^{*}-p}}
		\end{align*}
		\textit{Case II :}\par 
		using similar discussions as in Theorem \eqref{thm9}, $\exists$ $\lambda_{2}>0$ satisfyng,
		\begin{align*}
			c^{\lambda}_{n}\leq \Phi_{n}<\left(\frac{1}{\theta}-\frac{1}{p^{*}}\right)\left(m_{0}C_{p^{*}}\right)^{\frac{p^{*}}{p^{*}-p}} \hspace{40pt}\forall \mbox{ }\lambda>\lambda_{2}.
		\end{align*}
		Thus, in any case, we must obtain,
		\begin{align*}
			0<c^{\lambda}_{1}\leq c^{\lambda}_{2}\leq \cdots \leq c^{\lambda}_{n}<\Phi_{n}<\left(\frac{1}{\theta}-\frac{1}{p^{*}}\right)\left(m_{0}C_{p^{*}}\right)^{\frac{p^{*}}{p^{*}-p}}
		\end{align*}
		Applying similar arguments as described in \cite{52}, we can in fact guarantee that, the levels, $c^{\lambda}_{1}\leq c^{\lambda}_{2}\leq \cdots \leq c^{\lambda}_{n}$ are indeed the \textit{critical values} of $\mathcal{J}_{\lambda}$.\par 
		If $c^{\lambda}_{j}=c^{\lambda}_{j+1}$ for some $j=1,2,\cdots k-1$, therefore, by \cite[Theorem~$4.2$, Remark~$2.12$]{53}, the set $K_{c^{\lambda}_{j}}$ contains infinitely many distinct points, and hence, the problem \eqref{30} has \textbf{infinitely many weak solutions}. \par 
		Finally thus we conclude that, the problem \eqref{30} has at least $k$ pairs of solutions, and the proof is done.

